const setDocumentASNIfFree = `-- name: SetDocumentASNIfFree :execrows
UPDATE documents SET asn = ?1
WHERE documents.workspace_id = ?2 AND documents.id = ?3
  AND NOT EXISTS (SELECT 1 FROM documents AS o WHERE o.workspace_id = ?2 AND o.asn = ?1)
`

type SetDocumentASNIfFreeParams struct {
	Asn         sql.NullInt64 `json:"asn"`
	WorkspaceID int64         `json:"workspace_id"`
	ID          int64         `json:"id"`
}

// An archive serial number from an ASN barcode, only if no document of the
// workspace has it yet.
func (q *Queries) SetDocumentASNIfFree(ctx context.Context, arg SetDocumentASNIfFreeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setDocumentASNIfFree, arg.Asn, arg.WorkspaceID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

